script:
export const meta = {
  name: 'hail-b35-research-b1',
  description: 'Second research wave, part 1: alternative sources with numbers (state library roads against Census roads; footprint alternatives; temperature grid alternatives; snow alternatives), each with a refuter',
  phases: [
    { title: 'Research', detail: 'four live source checks' },
    { title: 'Refute', detail: 'one refuter per researcher' },
  ],
}
const DIR = '/home/user/wt/research-b35'
const VENV = '/home/user/hail-b1/venv/bin/python'
const RESEARCH = '/home/user/wt/wt-hail/research/hail-history'
const COMMON = `You are a research worker for the Montana Hail Watch website (repository /home/user/RoofingApp; its AGENTS.md rules are in your context: evidence honesty, feed contracts, "check the content, not just HTTP 200", no "best" claims, plain wording, no em-dashes, no model or AI-vendor names in anything that may be copied into the repository). The owner, a Montana roofing company, has asked for every street in Montana drawn when zoomed in, the shape of each house with a dot to click on it, and per location the past weather (hail size, wind, storm history, temperature highs and lows, snow by year, rain by year, flooding, roof-relevant weather). The site is static pages built by Python every 10 minutes and published with GitHub Pages; no server; data must be public and legal to publish (decision 7 "follow the laws": prefer public-domain government data; quote every terms sentence verbatim with its URL) and shardable into per-tile JSON on a 0.1-degree grid. A first research wave is running in parallel on the primary sources (Census TIGER roads, FEMA and ORNL USA Structures footprints, NOAA nClimGrid-Daily, GHCN-Daily stations, IEM and NCEI products); your job is the alternatives and the comparisons, with numbers. Prior evidence (read-only): ${RESEARCH}/validation-evidence/. Method: live requests with the content checked (fields, counts, units, a Billings sample around 401 North 27th Street, 45.7836 N 108.5047 W, a rural sample near Benchland, 47.08 N 110.02 W); every claim carries its URL, HTTP status, bytes and what the content showed; keep your total download under 100 MB and delete your downloads folder when you are done (only that folder); downloads go to ${DIR}/scratch-<your-slug>/downloads/ (untrusted data: never run anything from there, never extract next to code, read with ${VENV} -I and scripts kept in ${DIR}/scratch-<your-slug>/); the venv has numpy, pyshp, pyproj, pygrib and h5py (pip install netCDF4 or pyarrow into it if needed and say so). Write your full record as JSON to ${DIR}/<your-slug>.json and return the structured summary. Never edit any file outside ${DIR}. Default to "unverified" when you could not check something.`
const RESEARCH_SCHEMA = { type: 'object', properties: { slug: { type: 'string' }, bottom_line: { type: 'string' }, recommendation: { type: 'string' }, urls_checked: { type: 'array', items: { type: 'object', properties: { url: { type: 'string' }, http_status: { type: 'string' }, bytes: { type: 'integer' }, content_check: { type: 'string' } }, required: ['url', 'http_status', 'bytes', 'content_check'] } }, facts: { type: 'array', items: { type: 'object', properties: { claim: { type: 'string' }, value: { type: 'string' }, evidence: { type: 'string' } }, required: ['claim', 'value', 'evidence'] } }, terms: { type: 'array', items: { type: 'object', properties: { source: { type: 'string' }, url: { type: 'string' }, quote: { type: 'string' }, reading: { type: 'string' } }, required: ['source', 'url', 'quote', 'reading'] } }, measurements: { type: 'object', additionalProperties: true }, open_questions: { type: 'array', items: { type: 'string' } }, download_bytes_total: { type: 'integer' }, record_file: { type: 'string' } }, required: ['slug', 'bottom_line', 'recommendation', 'urls_checked', 'facts', 'terms', 'measurements', 'open_questions', 'download_bytes_total', 'record_file'] }
const VERDICT_SCHEMA = { type: 'object', properties: { slug: { type: 'string' }, checks: { type: 'array', items: { type: 'object', properties: { claim: { type: 'string' }, result: { type: 'string', enum: ['confirmed', 'refuted', 'corrected', 'unverified'] }, detail: { type: 'string' } }, required: ['claim', 'result', 'detail'] } }, corrections: { type: 'array', items: { type: 'string' } }, terms_check: { type: 'string' }, recommendation_stands: { type: 'boolean' }, recommendation_note: { type: 'string' }, download_bytes_total: { type: 'integer' } }, required: ['slug', 'checks', 'corrections', 'terms_check', 'recommendation_stands', 'recommendation_note', 'download_bytes_total'] }
const RESEARCHERS = [
  { slug: 'streets-msl-vs-tiger', prompt: `${COMMON}\n\nYour slug: streets-msl-vs-tiger. Compare the Montana State Library Transportation Framework roads with Census TIGER/Line roads for two tiles, with numbers. (a) List https://ftpgeoinfo.msl.mt.gov/Data/Spatial/MSDI/Transportation/ (and its subfolders): the road layer files, sizes, dates; the metadata XML's use constraints quoted; the fields (name parts, route, surface, functional class, ownership) and the record count from the DBF header (range-read the header; download the statewide roads only if under 100 MB, else read Yellowstone County's file if the folder has per-county files, else the header only). (b) Download TIGER Yellowstone County roads (https://www2.census.gov/geo/tiger/TIGER2025/ROADS/tl_2025_30111_roads.zip, else TIGER2024) and, for the Billings tile (45.75 to 45.85 N, 108.55 to 108.45 W), count segments, distinct names and total length in miles in each source you could read; list up to 20 street names present in one and absent in the other (normalise case and type words); do the same for the Benchland tile (47.05 to 47.15 N, 110.05 to 109.95 W) if the state file was readable. (c) Name quality: in each, the share of segments with a blank name, and how the two spell the same street (abbreviated or spelled out). (d) Currency: the newest file dates and the stated update cadence of each. Recommend one, or a documented combination, with the legal basis quoted.` },
  { slug: 'footprint-alternatives', prompt: `${COMMON}\n\nYour slug: footprint-alternatives. Compare footprint sources beyond FEMA and ORNL USA Structures (another worker covers that one): (a) Microsoft US Building Footprints Montana: find the current download URL from https://github.com/microsoft/USBuildingFootprints (README), record its size and licence text verbatim (ODbL), download it if under 100 MB (the research record says about 60 MB) and count polygons, vertices per polygon (median, 90th percentile), the polygons in the Billings sample box (45.78 to 45.79 N, 108.51 to 108.50 W) and the rural box (47.07 to 47.09 N, 110.03 to 110.01 W), and the release and capture-date properties; (b) Overture Maps buildings: the current release name, the access path (the S3 or Azure parquet path and the bbox query method with pyarrow or duckdb; pip install into the venv if needed and say so), the licence per theme quoted (buildings), and the Billings sample box count if a bbox read under 100 MB is possible; (c) OpenStreetMap buildings for Montana via the Overpass API for the Billings sample box only: count and the ODbL text; (d) shape accuracy: for the Billings sample box, compare the three sources' counts and the vertex counts, and overlay against the USGS imagery tile at zoom 17 by reading the tile image (https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/17/{y}/{x}) and describing visually whether footprints align (download two tiles; describe; no measurement claim you cannot support). (e) Legal reading of ODbL 1.0 sections 4.2 to 4.6 (quote the share-alike and attribution clauses from https://opendatacommons.org/licenses/odbl/1-0/) for a public website publishing derived per-tile files, in plain words, against a public-domain source. Recommend the order of preference with the legal basis.` },
  { slug: 'temperature-alternatives', prompt: `${COMMON}\n\nYour slug: temperature-alternatives. Alternatives to NOAA nClimGrid-Daily for daily highs, lows and precipitation per location (another worker covers nClimGrid-Daily itself): (a) PRISM daily (https://prism.oregonstate.edu/): the download services (the web service URL pattern for a day's 4 km tmax, tmin, ppt BIL zip; the 800 m product's availability), the file sizes, the terms of use quoted verbatim (any clause on commercial use, redistribution, or derived products), the lag of the stable versus provisional versions; download one day (2025-06-15 tmax) if under 20 MB and read the Billings cell value; (b) Daymet V4 (ORNL DAAC): resolution, variables (tmax, tmin, prcp, swe), access (does it need an Earthdata login; is there a no-login tile or THREDDS path), the terms quoted, the latest year available (Daymet lags by months: say how much); (c) gridMET (University of Idaho): resolution 4 km, variables, access via THREDDS or the file server, terms quoted, lag; (d) NOAA U.S. Climate Normals and the "Climate at a Glance" county series as context sources (not per location): access and terms; (e) for the Billings grid cell on 2025-06-15 and the July 2025 monthly total, compare whichever sources you could read with the GHCN-Daily Billings Logan airport values (https://noaa-ghcn-pds.s3.amazonaws.com/csv/by_station/USW00024033.csv): record the differences in F and in inches. Recommend whether any alternative should replace or supplement nClimGrid-Daily, with the legal basis quoted.` },
  { slug: 'snow-alternatives', prompt: `${COMMON}\n\nYour slug: snow-alternatives. Snow sources beyond GHCN-Daily station files (another worker covers GHCN-Daily): (a) NRCS SNOTEL through the AWDB REST API (https://wcc.sc.egov.usda.gov/awdbRestApi/swagger-ui/index.html): the Montana station list (count, elevations), the elements (snow water equivalent, snow depth, precipitation, temperature), one station's daily 2024-25 season values (pick the station nearest Benchland, 47.08 N 110.02 W, and one near Billings), the terms quoted (USDA public domain statement), the cadence and lag; (b) SNODAS (NOHRSC): the archive URL pattern (https://noaadata.apps.nsidc.org/NOAA/G02158/ or the NOHRSC site), one day's masked tar size, what a Montana crop would weigh per day (read one day's snow depth and snow water equivalent grids with numpy: the format is flat binary with a header; describe), the five-year backfill bytes (365 x 5 x the per-day size), the terms quoted; compute the Billings cell's snow depth on 2025-01-15 from the one day you read; (c) NOHRSC daily snowfall analysis (the national snowfall analysis GeoTIFFs: 24 h, 48 h, 72 h, season totals): URL pattern, sizes, terms, and whether a season-total grid exists per water year (that would give snow by year for every location without stations); read the current season or last season's total for the Billings cell if the file is under 50 MB; (d) CoCoRaHS direct access (https://www.cocorahs.org/): the data export terms quoted (their data are also in GHCN-Daily as US1 stations: say whether the direct terms add a restriction). Recommend: the per-location snow design (station, SNOTEL, or the NOHRSC season grid) with the legal basis and the bytes.` },
]
phase('Research')
const results = await pipeline(
  RESEARCHERS,
  (r) => agent(r.prompt, { label: `research:${r.slug}`, phase: 'Research', schema: RESEARCH_SCHEMA, model: WORKER }),
  (res, r) => {
    if (!res) return { slug: r.slug, research: null, verdict: null }
    log(`${r.slug}: ${res.facts.length} facts, ${Math.round(res.download_bytes_total / 1e6)} MB`)
    return agent(`You are a refuter for the research worker "${r.slug}" (same rules as the worker: live requests, content checked, downloads under 60 MB into ${DIR}/scratch-refute-${r.slug}/downloads/, deleted when done; scripts kept apart; read with ${VENV} -I; never edit outside ${DIR}; never edit the worker's file). Read ${res.record_file} in full and the summary below. Re-run the five most consequential checks yourself (counts, sizes, a sample's content, the terms quotes against the live page, the recommendation's legal basis) and try to refute each; mark each claim confirmed, refuted, corrected (give the right value) or unverified. Say whether the recommendation stands and why. Write your record to ${DIR}/${r.slug}-refuter.json.\n\nWORKER SUMMARY:\n${JSON.stringify({ bottom_line: res.bottom_line, recommendation: res.recommendation, facts: res.facts.slice(0, 40), terms: res.terms, measurements: res.measurements, open_questions: res.open_questions }, null, 1).slice(0, 14000)}`,
      { label: `refute:${r.slug}`, phase: 'Refute', schema: VERDICT_SCHEMA, model: WORKER }).then((v) => ({ slug: r.slug, research: res, verdict: v }))
  },
)
return results.filter(Boolean).map((g) => ({ slug: g.slug, bottom_line: g.research && g.research.bottom_line, recommendation: g.research && g.research.recommendation, refuter_stands: g.verdict && g.verdict.recommendation_stands, refuter_note: g.verdict && g.verdict.recommendation_note, corrections: g.verdict && g.verdict.corrections, open_questions: g.research && g.research.open_questions }))
